const MATERIAL_IMAGE_DATA = {
  cu_coupling: 'data:image/webp;base64,',
  cu_elbow_90: 'data:image/webp;base64,',
  cu_pipe: 'data:image/webp;base64,',
  cu_tee: 'data:image/webp;base64,',
  ht_elbow_90: 'data:image/webp;base64,',
  ht_pipe: 'data:image/webp;base64,',
  ppr_elbow_90: 'data:image/webp;base64,',
  ppr_tee: 'data:image/webp;base64,',
};

const MATERIAL_IMAGE_MAP = {
  'cu|trubka': MATERIAL_IMAGE_DATA.cu_pipe,
  'cu|koleno 90°': MATERIAL_IMAGE_DATA.cu_elbow_90,
  'cu|t-kus': MATERIAL_IMAGE_DATA.cu_tee,
  'cu|spojka': MATERIAL_IMAGE_DATA.cu_coupling,
  'ppr|koleno 90°': MATERIAL_IMAGE_DATA.ppr_elbow_90,
  'ppr|t-kus': MATERIAL_IMAGE_DATA.ppr_tee,
  'ht|trubka': MATERIAL_IMAGE_DATA.ht_pipe,
  'ht|koleno 90°': MATERIAL_IMAGE_DATA.ht_elbow_90,
};

export function getMaterialImage(item) {
  if (!item) return null;
  if (item.imageUrl) return item.imageUrl;
  const category = String(item.categoryKey || item.categoryLabel || '').trim().toLowerCase();
  const type = String(item.type || '').trim().toLowerCase();
  return MATERIAL_IMAGE_MAP[`${category}|${type}`] || null;
}

export function getMaterialCategoryImage(categoryKey) {
  const key = String(categoryKey || '').trim().toLowerCase();
  return {
    cu: MATERIAL_IMAGE_DATA.cu_pipe,
    ppr: MATERIAL_IMAGE_DATA.ppr_elbow_90,
    ht: MATERIAL_IMAGE_DATA.ht_pipe,
  }[key] || null;
}
